CREATE TABLE IF NOT EXISTS users (id VARCHAR(40) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, active INTEGER NOT NULL DEFAULT 1, auth_version INTEGER NOT NULL DEFAULT 1, mfa_secret TEXT, mfa_last INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (user_id VARCHAR(40) PRIMARY KEY, phone TEXT, birth_date VARCHAR(12), city VARCHAR(100), identity_number TEXT, guardian_name TEXT, guardian_phone TEXT, guardian_id VARCHAR(40), consent_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(guardian_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS courses (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, category VARCHAR(100) NOT NULL, image VARCHAR(200) NOT NULL, status VARCHAR(20) NOT NULL, instructor_id VARCHAR(40), duration INTEGER NOT NULL DEFAULT 0, capacity INTEGER NOT NULL DEFAULT 20, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(instructor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS enrollments (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, UNIQUE(course_id,student_id), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS lessons (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, kind VARCHAR(20) NOT NULL, video_url TEXT, file_id VARCHAR(40), body TEXT, duration INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS progress (id VARCHAR(40) PRIMARY KEY, lesson_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, completed_at VARCHAR(30) NOT NULL, UNIQUE(lesson_id,student_id), FOREIGN KEY(lesson_id) REFERENCES lessons(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assignments (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, due_at VARCHAR(30) NOT NULL, points INTEGER NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS submissions (id VARCHAR(40) PRIMARY KEY, assignment_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, body TEXT NOT NULL, file_id VARCHAR(40), score INTEGER, feedback TEXT, submitted_at VARCHAR(30) NOT NULL, UNIQUE(assignment_id,student_id), FOREIGN KEY(assignment_id) REFERENCES assignments(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS quizzes (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, minutes INTEGER NOT NULL, passing INTEGER NOT NULL, max_attempts INTEGER NOT NULL, questions TEXT NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS attempts (id VARCHAR(40) PRIMARY KEY, quiz_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, started_at VARCHAR(30) NOT NULL, expires_at VARCHAR(30) NOT NULL, submitted_at VARCHAR(30), answers TEXT, questions TEXT NOT NULL, score INTEGER, total INTEGER NOT NULL, FOREIGN KEY(quiz_id) REFERENCES quizzes(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS classes (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, starts_at VARCHAR(30) NOT NULL, ends_at VARCHAR(30) NOT NULL, location VARCHAR(160) NOT NULL, join_url TEXT, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS attendance (id VARCHAR(40) PRIMARY KEY, class_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, note TEXT, recorded_by VARCHAR(40) NOT NULL, updated_at VARCHAR(30) NOT NULL, UNIQUE(class_id,student_id), FOREIGN KEY(class_id) REFERENCES classes(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS files (id VARCHAR(40) PRIMARY KEY, owner_id VARCHAR(40) NOT NULL, course_id VARCHAR(40), student_id VARCHAR(40), purpose VARCHAR(30) NOT NULL, name VARCHAR(180) NOT NULL, mime VARCHAR(100) NOT NULL, bytes INTEGER NOT NULL, storage_name VARCHAR(100) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS announcements (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40), title VARCHAR(200) NOT NULL, body TEXT NOT NULL, author_id VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS certificates (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, serial VARCHAR(60) NOT NULL UNIQUE, issued_at VARCHAR(30) NOT NULL, UNIQUE(course_id,student_id), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit (id VARCHAR(40) PRIMARY KEY, actor_id VARCHAR(40), action VARCHAR(100) NOT NULL, entity_id VARCHAR(100), created_at VARCHAR(30) NOT NULL, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (bucket VARCHAR(100) PRIMARY KEY, hits INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS support (id VARCHAR(40) PRIMARY KEY, user_id VARCHAR(40) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, reply TEXT, status VARCHAR(20) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS legacy_links (id VARCHAR(40) PRIMARY KEY, kind VARCHAR(30) NOT NULL, legacy_id VARCHAR(100) NOT NULL, new_id VARCHAR(40) NOT NULL, payload TEXT, UNIQUE(kind,legacy_id));
CREATE INDEX IF NOT EXISTS enrollments_student ON enrollments(student_id);
CREATE INDEX IF NOT EXISTS lessons_course ON lessons(course_id,sort_order);
CREATE INDEX IF NOT EXISTS profiles_guardian ON profiles(guardian_id);
CREATE INDEX IF NOT EXISTS classes_course ON classes(course_id,starts_at);
CREATE INDEX IF NOT EXISTS files_course ON files(course_id);
CREATE INDEX IF NOT EXISTS audit_created ON audit(created_at);
